require "rails_helper"

RSpec.describe "Timekeeping internal handoff correction snapshots" do
  include_context "timekeeping entry writes without transactional fixtures"

  around { |example| with_handoff_env(public_key: true) { example.run } }

  def put_handoff_corrections(snapshots)
    handoff_request(:correction_snapshots, body: { generation: 2, version: 1, snapshots: })
    [response.status, response.parsed_body]
  end

  def stored_handoff_corrections
    OutboxSnapshot.order(:outbox_position).pluck(:company_id, :id, :generation, :version, :locked)
  end

  def create_corrected_entry
    Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                  note: "Corrected", bill_status: "unbilled", source: "manual", source_metadata: {})
  end

  # "Writing the same corrections again replaces them, so there is never a
  # second snapshot for one entry and generation."
  it "keeps one correction snapshot per entry, at version 1 and the new generation, when the same corrections arrive twice" do
    first = create_corrected_entry
    second = create_corrected_entry
    Timekeeping::Admission.fence!
    corrections = [handoff_correction_snapshot(first, locked: false), handoff_correction_snapshot(second, locked: false)]

    expect(put_handoff_corrections(corrections)).to eq([200, { "written" => 2 }])
    expect(put_handoff_corrections(corrections)).to eq([200, { "written" => 2 }])

    # "The first cutover writes one per corrected entry, at version 1 and the new generation."
    expect(stored_handoff_corrections).to contain_exactly([1, first.id, 2, 1, false], [1, second.id, 2, 1, false])
  end

  # A refused request must not delete corrections already written, so the
  # stored rows are written first and compared whole after the refusal.
  it "refuses one request naming the same entry twice and keeps the corrections already written" do
    first = create_corrected_entry
    second = create_corrected_entry
    Timekeeping::Admission.fence!
    corrections = [handoff_correction_snapshot(first, locked: false), handoff_correction_snapshot(second, locked: false)]
    expect(put_handoff_corrections(corrections)).to eq([200, { "written" => 2 }])
    expect(stored_handoff_corrections).to contain_exactly([1, first.id, 2, 1, false], [1, second.id, 2, 1, false])
    # Every column of every stored row, outbox_position included, so a refusal
    # that replaced a snapshot before rejecting the request is caught.
    before = handoff_stored_rows

    duplicate = [handoff_correction_snapshot(first, locked: false), handoff_correction_snapshot(first, locked: true)]

    expect(put_handoff_corrections(duplicate)).to eq([400, { "reason" => "invalid_request" }])
    expect(handoff_stored_rows).to eq(before)
  end

  it "stores a decimal sent as a bare JSON number exactly" do
    at = Time.utc(2026, 3, 2, 9)
    Entry.insert_all!([{ id: 31, company_id: 1, version: 0, project_id: 10, user_id: 20,
                         work_date: Date.new(2026, 3, 2), duration: 30.0, bill_status: "unbilled",
                         created_at: at, updated_at: at }])
    Timekeeping::Admission.fence!
    snapshot = Timekeeping::Handoff::CorrectionSnapshots::SNAPSHOT_FIELDS.index_with { nil }.merge(
      "id" => 31, "company_id" => 1, "project_id" => 10, "user_id" => 20, "work_date" => "2026-03-02",
      "duration" => 30.0, "note" => "", "bill_status" => "unbilled", "review_status" => "not_required",
      "locked" => true, "source" => "manual", "source_metadata" => { "rate" => BigDecimal("1.00000000000000000001") },
      "proof_metadata" => {}, "created_at" => at.iso8601, "updated_at" => at.iso8601
    )
    body = Timekeeping::Handoff::LosslessSql.json_text("generation" => 2, "version" => 1, "snapshots" => [snapshot])

    handoff_request(:correction_snapshots, body:)

    expect([response.status, response.parsed_body]).to eq([200, { "written" => 1 }])
    expect(ApplicationRecord.connection.select_value("SELECT source_metadata::text FROM outbox_snapshots WHERE id = 31"))
      .to eq('{"rate": 1.00000000000000000001}')
  end
end

RSpec.describe "Timekeeping internal handoff correction snapshots stay within one company" do
  include_context "timekeeping entry writes without transactional fixtures"

  around { |example| with_handoff_env(public_key: false) { example.run } }

  # "Writing the same corrections again replaces them, so there is never a
  # second snapshot for one entry and generation."
  it "replaces only the corrected company's snapshot and leaves another company's snapshot with the same entry id and generation" do
    entry = Entry.create!(id: 301, company_id: 1, user_id: 21, project_id: 11, work_date: "2026-03-02",
                          duration: 60.0, note: "", bill_status: "unbilled", locked: true, source: "manual",
                          source_metadata: {})
    # Company 2 holds a snapshot for the same entry id at the same generation.
    OutboxSnapshot.insert_all!([handoff_correction_snapshot(entry, locked: true)
      .merge("company_id" => 2, "version" => 4, "generation" => 2)])
    Timekeeping::Admission.fence!
    body = { generation: 2, version: 1, snapshots: [handoff_correction_snapshot(entry, locked: false)] }

    2.times do
      handoff_request(:correction_snapshots, body:)
      expect(response.status).to eq(200)
    end

    rows = OutboxSnapshot.where(id: 301, generation: 2).order(:company_id).pluck(:company_id, :version, :locked)
    expect(rows).to eq([[1, 1, false], [2, 4, true]])
  end
end
